CREATE TABLE IF NOT EXISTS players ( id TEXT PRIMARY KEY, google_sub TEXT NOT NULL UNIQUE, email TEXT NOT NULL, name TEXT, nickname TEXT, nickname_key TEXT UNIQUE, avatar INTEGER NOT NULL DEFAULT 0, show_on_boards INTEGER NOT NULL DEFAULT 1, consent_at INTEGER NOT NULL, created_at INTEGER NOT NULL, last_seen_at INTEGER NOT NULL ); CREATE TABLE IF NOT EXISTS sessions ( token_hash TEXT PRIMARY KEY, player_id TEXT NOT NULL REFERENCES players(id) ON DELETE CASCADE, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL ); CREATE INDEX IF NOT EXISTS sessions_player ON sessions(player_id); CREATE TABLE IF NOT EXISTS anon_links ( anon_id TEXT PRIMARY KEY, player_id TEXT NOT NULL REFERENCES players(id) ON DELETE CASCADE, linked_at INTEGER NOT NULL ); 
